from pathlib import Path
p = Path('tinydb/queries.py')
s = p.read_text()
needle = """        return QueryInstance(lambda value: self(value) or other(value), hashval)

    def __invert__(self) -> 'QueryInstance':
"""
replacement = """        return QueryInstance(lambda value: self(value) or other(value), hashval)

    def __and__(self, other: 'QueryInstance') -> 'QueryInstance':
        # We use a frozenset because AND is commutative.
        if self.is_cacheable() and other.is_cacheable():
            hashval = ('and', frozenset([self._hash, other._hash]))
        else:
            hashval = None
        return QueryInstance(lambda value: self(value) and other(value), hashval)

    def __invert__(self) -> 'QueryInstance':
"""
if needle not in s:
    raise SystemExit('expected insertion point not found')
p.write_text(s.replace(needle, replacement, 1))
